import com.mongodb.client.MongoClients;
import com.mongodb.client.MongoClient;
import com.mongodb.client.MongoDatabase;
import com.mongodb.client.MongoCollection;
import org.bson.Document;

public class Main {
  public static void main(String[] args) {
      MongoClient client = MongoClients.create("mongodb://localhost:27017");
      MongoDatabase db = client.getDatabase("mibasededatos");

      // En Java declaramos el tipo que guardará la colección, usualmente un Document de BSON
      MongoCollection<Document> collection = db.getCollection("clientes");

      System.out.println(collection.getNamespace());
  }
}
